/* ===== Persistir historial de Bloqueos prolongados ===== */
SET NOCOUNT ON;

IF OBJECT_ID('OpsObservability.dbo.monitoring_blocking_longwaits_history','U') IS NULL
BEGIN
  CREATE TABLE OpsObservability.dbo.monitoring_blocking_longwaits_history(
    id             bigint         IDENTITY(1,1) PRIMARY KEY,
    ts_utc         datetime2      NOT NULL,
    instance_name  sysname        NOT NULL,
    fecha_bloqueo  datetime2      NULL,
    session_id     int            NULL,
    bloqueado_por  sysname        NULL,
    wait_seconds   decimal(18,2)  NULL,
    consulta       nvarchar(max)  NULL,
    estado         nvarchar(20)   NULL
  );
END;

/* === Variables provenientes del item actual de n8n === */
DECLARE
  @instance_name  sysname       = N'{{$json["instance_name"]}}',
  @ts_sp_raw      nvarchar(50)  = N'{{$json["ts_sp"]}}',
  @session_id     int           = {{$json["session_id"]}},
  @bloqueado_por  sysname       = N'{{$json["bloqueado_por"]}}',
  @wait_seconds   decimal(18,2) = {{$json["wait_seconds"]}},
  -- Escapamos comillas simples de la consulta para que no rompa el SQL
  @consulta       nvarchar(max) = N'{{ ($json["consulta"] || "").replace(/'/g, "''") }}',
  @estado         nvarchar(20)  = N'{{$json["estado"]}}';

DECLARE @fecha_bloqueo datetime2;

/* Conversión segura de la fecha que viene como string ISO (ej: 2025-11-25T13:48:47.447Z) */
IF @ts_sp_raw IS NULL OR @ts_sp_raw = N''
BEGIN
  SET @fecha_bloqueo = NULL;
END
ELSE
BEGIN
  -- Quitamos la 'Z' final si viene, y cambiamos 'T' por espacio
  DECLARE @clean nvarchar(30) = REPLACE(LEFT(@ts_sp_raw, 23), 'T', ' ');
  IF ISDATE(@clean) = 1
    SET @fecha_bloqueo = CAST(@clean AS datetime2);
  ELSE
    SET @fecha_bloqueo = NULL;
END;

/* Insert del registro en el historial */
INSERT INTO OpsObservability.dbo.monitoring_blocking_longwaits_history(
  ts_utc,
  instance_name,
  fecha_bloqueo,
  session_id,
  bloqueado_por,
  wait_seconds,
  consulta,
  estado
)
VALUES(
  SYSUTCDATETIME(),
  @instance_name,
  @fecha_bloqueo,
  @session_id,
  @bloqueado_por,
  @wait_seconds,
  @consulta,
  @estado
);

