function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (ALERTA Bloqueos prolongados) ===
const P = $node["Set - Params"].json || {};
const j = $json;

const alerts = j.alerts || [];
if (!alerts.length) return [];

const tzOff = Number(P.tz_offset_hours || 0);
const toLocal = iso => {
  if (!iso) return "N/D";
  const d = new Date(iso);
  const offMs = tzOff * 3600 * 1000;
  return new Date(d.getTime() + offMs)
    .toISOString().replace("T"," ").substring(0,19);
};
const trunc = (s, n) => {
  const t = String(s ?? "");
  return t.length <= n ? t : t.slice(0, n - 1) + "…";
};

const inst    = j.instance_name || "N/D";
const nowIso  = j.ts_utc || new Date().toISOString();

// Cada bloqueo en una línea
const lines = alerts.map(r => {
  const sessionId    = r.session_id ?? r.SessionID ?? "N/D";
  const bloqueadoPor = r.bloqueado_por ?? r.BloqueadoPor ?? "N/D";
  const wait         = r.wait_seconds ?? r.Tiempo_Espera_Segundos ?? 0;
  const ts           = r.ts_sp ? toLocal(r.ts_sp) : "N/D";
  const sql          = r.consulta ?? r.Consulta ?? "-";

  return `- **SessionID:** ${sessionId}  •  **Bloqueado por:** ${bloqueadoPor}  •  **Espera (s):** ${wait}  •  **Desde:** ${ts}\n  **Consulta:** ${trunc(sql, 300)}`;
});

const diag = [
  "- Se detectaron **bloqueos prolongados** en la instancia de SQL Server.",
  "- Una sesión está reteniendo recursos y mantiene a otras sesiones en espera durante demasiado tiempo.",
  "- Esto puede impactar tiempos de respuesta de la aplicación y generar timeout en los usuarios."
].join("\n");

const sugg = [
  "- Identificar la sesión bloqueadora principal y revisar su consulta / plan de ejecución.",
  "- Validar si existen índices faltantes, estadísticas desactualizadas o consultas que requieren optimización.",
  "- Revisar si hay jobs de mantenimiento o procesos masivos ejecutándose en horas de alta carga.",
  "- Considerar aplicar kill controlado de sesiones bloqueadoras solo si se valida el impacto funcional."
].join("\n");

const title = `${P.title_prefix || "ALERTA – Bloqueos prolongados"} • ${inst}`;

return {
  json: {
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: "C0392B",
    summary: title,
    title,
    sections: [
      {
        markdown: true,
        text: `🔴 **ALERTA – Bloqueos prolongados detectados**\n\nInstancia: **${inst}**\nBloqueos en esta ejecución: **${alerts.length}**\nHora local: ${toLocal(nowIso)}`
      },
      {
        markdown: true,
        text: `📄 **Detalle de bloqueos**\n\n${lines.join("\n")}`
      },
      {
        markdown: true,
        text: `📌 **Diagnóstico posible**\n${diag}`
      },
      {
        markdown: true,
        text: `✅ **Sugerencias**\n${sugg}`
      }
    ]
  }
};

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build Teams payload (RECOVERY) — Bloqueos prolongados ===
const j = $json;

const recovered   = j.recovered_items || [];
const stillAlerts = j.alerts || [];

let title = "";
const lines = [];

// Global vs parcial
if (j.send_recovery_global) {
  title = "RECOVERY – Bloqueos prolongados (todos OK)";
  lines.push(
    "Todas las sesiones monitoreadas por el SP `usp_MonitoreoBloqueosProlongados` están ahora en estado **OK** (sin bloqueos prolongados activos)."
  );
} else {
  title = "RECOVERY parcial – Bloqueos prolongados";
  lines.push(
    "Algunas sesiones se han recuperado, pero aún quedan sesiones en **ALERTA** por bloqueos prolongados."
  );
}

// Registros recuperados
if (recovered.length) {
  lines.push("");
  lines.push(`**Sesiones recuperadas (${recovered.length}):**`);
  lines.push("");

  recovered.forEach(r => {
    const sessionId    = r.SessionID || r.session_id || "N/D";
    const bloqueadoPor = r.BloqueadoPor || r.bloqueado_por || "N/D";
    const wait         = r.Tiempo_Espera_Segundos || r.wait_seconds || "N/D";
    const fecha        = r.FechaHora || r.fecha_hora || r.ts_sp || r.Fecha || r.fecha || "N/D";

    lines.push(`- **SessionID:** ${sessionId}  •  **Bloqueado por:** ${bloqueadoPor}  •  Último tiempo de espera registrado: ${wait} s  •  Último evento en alerta: ${fecha}`);
  });
}

// Registros que siguen en alerta
if (stillAlerts.length) {
  lines.push("");
  lines.push(`**Sesiones que siguen en alerta (${stillAlerts.length}):**`);
  lines.push("");

  stillAlerts.forEach(r => {
    const sessionId    = r.SessionID || r.session_id || "N/D";
    const bloqueadoPor = r.BloqueadoPor || r.bloqueado_por || "N/D";
    const estado       = r.Estado  || r.estado  || "Alerta";
    const wait         = r.Tiempo_Espera_Segundos || r.wait_seconds || "N/D";

    lines.push(`- **SessionID:** ${sessionId}  •  **Bloqueado por:** ${bloqueadoPor}  •  Estado actual: ${estado}  •  Espera actual (s): ${wait}`);
  });
}

const text = `### ${title}\n\n` + lines.join("\n");

return [
  {
    json: {
      body: {
        text,
      },
    },
  },
];

// === Function – Decidir estado (Bloqueos prolongados) con recovery por sesión ===

const P = $node["Set - Params"].json || {};

// Filas actuales (ya procesadas en "Function – Expand filas")
const rows = $items("Function – Expand filas").map(i => i.json);

// Helper: ¿la fila está en ALERTA?
const isAlert = (r) => {
  const e = String(r.estado || r.Estado || "").toUpperCase();
  return e.startsWith("ALERTA");   // Estado = 'Alerta'
};

// Clasificación actual
const alerts = rows.filter(isAlert);
const oks    = rows.filter(r => !isAlert(r));

// Estado global en memoria (igual patrón que otros flujos)
const staticData = $getWorkflowStaticData('global');

const last_state = staticData.last_state || "INIT";   // ALERT / OK / INIT
const state      = alerts.length > 0 ? "ALERT" : "OK";

staticData.last_state = state;

// Flags globales
const send_alert           = alerts.length > 0;
const send_recovery_global = (last_state === "ALERT" && state === "OK");

// Recovery por registro (SessionID + BloqueadoPor)
staticData.items     = staticData.items || {};     // registros en alerta última vez
staticData.recovered = staticData.recovered || {}; // registros ya notificados como recovery

const prevItems    = staticData.items;
const recoveredMap = staticData.recovered;

const getKey = (r) => {
  const sessionId    = r.session_id ?? r.SessionID ?? "";
  const bloqueadoPor = r.bloqueado_por ?? r.BloqueadoPor ?? "";
  return `${sessionId}|${bloqueadoPor}`;
};

// Conjunto actual de registros en alerta
const currentAlertSet = {};

for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;

  currentAlertSet[k] = true;   // sigue en alerta en esta corrida

  // Guardamos la última fila en alerta
  prevItems[k] = r;

  // Si ya lo habíamos marcado como recuperado y volvió a alerta, lo limpiamos
  if (recoveredMap[k]) {
    delete recoveredMap[k];
  }
}

// Registros que se recuperaron en esta corrida
const recovered_items = [];

for (const [k, lastRow] of Object.entries(prevItems)) {
  if (!currentAlertSet[k]) {
    if (!recoveredMap[k]) {
      recovered_items.push({
        ...lastRow,
        _recovery: true,
      });
      recoveredMap[k] = 1;   // marcado como ya notificado
    }
    delete prevItems[k];      // ya no está en alerta
  }
}

const send_recovery_partial = recovered_items.length > 0;

let transition = `${last_state}->${state}`;

const ts_utc = new Date().toISOString();

return [
  {
    json: {
      instance_name: P.instance_name || "N/D",

      ts_utc,
      state,
      last_state,
      transition,

      total: rows.length,
      alert_count: alerts.length,
      total_ok: oks.length,

      alerts,
      oks,
      recovered_items,

      send_alert,
      send_recovery_global,
      send_recovery_partial
    }
  }
];

